def comps(g, bg=3, col=7):
    import numpy as np
    a=np.array(g); H,W=a.shape
    mask=a==col; seen=np.zeros_like(mask); out=[]
    for r in range(H):
        for c in range(W):
            if mask[r,c] and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=True; comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not seen[ny,nx]:
                                seen[ny,nx]=True; st.append((ny,nx))
                out.append(comp)
    return out
